function lesson5Dialogue(){app.innerHTML=intro('HỘI THOẠI · BÀI 5','Nhờ giúp ôn thi và hẹn gặp.','Hai hội thoại được chép lại từ các trang bạn gửi.')+lesson2VoiceControls()+'<button class="btn secondary" id="pinyin">'+(showPinyin?'Ẩn':'Hiện')+' pinyin</button>'+lesson5Data.dialogues.map(([title,lines],d)=>'<h2>'+title+'</h2><button class="btn secondary" data-lesson5-full="'+d+'">▶ Nghe toàn hội thoại</button>'+lines.map(([name,zh,py,vi],i)=>'<article class="dialogue"><small>'+name+'</small><button class="text-button" data-lesson5-line="'+d+','+i+'" aria-label="Nghe câu '+(i+1)+'">▶</button><p class="han">'+zh+'</p>'+(showPinyin?'<p class="pinyin">'+py+'</p>':'')+'<p>'+vi+'</p></article>').join('')).join('')+lesson5References(6,9);bindLesson2Voice(lesson5Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelector('#pinyin').onclick=()=>{stopWordAudio();showPinyin=!showPinyin;lesson5Dialogue();};document.querySelectorAll('[data-lesson5-line]').forEach(b=>b.onclick=()=>{const[d,i]=b.dataset.lesson5Line.split(',').map(Number);lesson2Speak(lesson5Data.dialogues[d][1][i][1]);});document.querySelectorAll('[data-lesson5-full]').forEach(b=>b.onclick=()=>lesson2Speak(lesson5Data.dialogues[Number(b.dataset.lesson5Full)][1].map(l=>l[1]).join(' ')));}
function lesson5BTNCMarkup(file){const group=lesson5BTNC.find(g=>g.file===file);if(!group)return '<p class="sub">File chính Q2B5; xem phần đáp án BTNC trên trang tham khảo bên dưới.</p>'+lesson5BTNCReference();const id=lesson5BTNC.indexOf(group),saved=state.lesson5Exercises?.['btnc'+id]||{};return '<details class="lesson2-answer-key"><summary>Luyện nghe với 5 câu hỏi</summary><p class="sub">Câu hỏi tự luyện biên soạn từ bản ghi lời nghe, không phải bộ lựa chọn của đề BTNC gốc.</p><form id="lesson5BTNCForm'+id+'">'+group.questions.map((q,i)=>'<fieldset class="question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l5nc'+id+'q'+i+'" value="'+j+'" '+(String(saved[i]?.answer)===String(j)?'checked':'')+'> '+v+'</label>').join('')+'<div id="lesson5BTNCFeedback'+id+'-'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson5BTNCResult'+id+'" role="status"></p></form></details><details class="lesson2-answer-key"><summary>Bản ghi lời nghe và đáp án BTNC gốc</summary>'+group.transcript.map((t,i)=>'<p lang="zh-CN" style="white-space:pre-line">'+(i+1)+'. '+esc(t)+'</p>').join('')+'<p><b>Đáp án '+group.title+':</b> '+group.key.map((k,i)=>(i+1)+'. '+k).join(' · ')+'</p><p class="sub">Các chữ cái dùng đối chiếu với đề BTNC gốc; câu tự luyện phía trên có thứ tự lựa chọn riêng.</p>'+lesson5BTNCReference()+'</details>';}
function lesson5BTNCReference(){return '<details class="lesson2-reference"><summary>Xem trang đáp án BTNC bài 5</summary><img loading="lazy" style="max-width:100%;height:auto" src="images/lesson5/btnc-answers-page16.png" alt="Đáp án BTNC bài 5, trang 16 của PDF"></details>';}
function bindLesson5BTNC(){lesson5BTNC.forEach((group,id)=>{document.querySelector('#lesson5BTNCForm'+id).onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;group.questions.forEach((q,i)=>{const answer=form.get('l5nc'+id+'q'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson5BTNCFeedback'+id+'-'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson5Exercises=state.lesson5Exercises||{};state.lesson5Exercises['btnc'+id]=records;save();document.querySelector('#lesson5BTNCResult'+id).textContent='Đúng '+count+' / 5 câu.';};});}

