function lesson5References(first=1,last=13){return '<details class="lesson2-reference"><summary>Xem trang giáo trình gốc</summary>'+Array.from({length:last-first+1},(_,i)=>'<figure><img loading="lazy" src="images/lesson5/source-'+(first+i)+'.png" alt="Bài 5 · ảnh nguồn '+(first+i)+'"><figcaption>Trang '+lesson5SourcePages[first+i-1]+'</figcaption></figure>').join('')+'</details>';}
function lesson5Home(){app.innerHTML=intro('HSK2 · LESSON 5',lesson5Data.title,lesson5Data.pinyin+' · '+lesson5Data.vi)+'<section class="hero"><div><h2>Gọi điện & hẹn cuối tuần</h2><p>Nhờ giúp ôn thi, hỏi lúc rảnh và cùng sắp xếp lịch hẹn.</p><a class="btn" href="#words">Học 20 mục từ →</a></div><div class="hero-mark" aria-hidden="true">约</div></section><div class="stats"><div class="stat"><small>TỪ ĐÃ NHỚ</small><strong>'+state.known.length+'<small> / 20</small></strong></div><div class="stat"><small>HỘI THOẠI</small><strong>02</strong></div><div class="stat"><small>TRANG GIÁO TRÌNH</small><strong>51–63</strong></div></div><div class="grid">'+[['words','Từ vựng','Nghe & gõ · Flashcard · Ghép từ'],['grammar','Ngữ pháp','跟、给 · 有点儿 và 一点儿'],['dialogue','Hội thoại','Hẹn giúp ôn thi · Hẹn uống cà phê'],['practice','Luyện tập','Điền từ · Đọc hiểu · Lập lịch hẹn'],['listening','Luyện nghe','Bốn file Q2B5 · Bản ghi BTNC · Tự luyện'],['writing','Luyện viết','Chữ Hán trong bài 5']].map(([id,title,desc])=>'<a class="card card-link" href="#'+id+'"><h3>'+title+' ↗</h3><p>'+desc+'</p></a>').join('')+'</div><article class="card grammar"><h2>Khởi động</h2><p>你常常给朋友打电话吗？<br>你可以用汉语打电话吗？<br>在什么情况下，你会打电话向朋友求助？</p></article>'+lesson5References();}
function lesson5Grammar(){app.innerHTML=intro('NGỮ PHÁP · BÀI 5','Gọi điện và nói mức độ nhẹ.','跟、给 đứng trước động từ; 有点儿 khác với 一点儿.')+`<article class="card grammar"><h2>01 · Cụm giới từ 跟 và 给</h2><div class="pattern">Chủ ngữ + 跟 / 给 + người + động từ</div><p><b>跟</b>: với, cùng ai. <b>给</b>: hướng tới người nhận của hành động.</p>${grammarExamples([["他星期天要跟朋友一起吃饭。","Tā xīngqītiān yào gēn péngyou yìqǐ chī fàn.","Chủ nhật anh ấy sẽ ăn cơm cùng bạn."],["我每个星期给妈妈打电话。","Wǒ měi ge xīngqī gěi māma dǎ diànhuà.","Mỗi tuần tôi gọi điện cho mẹ."],["你跟我来。","Nǐ gēn wǒ lái.","Bạn đi theo tôi."]])}</article><article class="card grammar"><h2>02 · 有点儿 + tính từ</h2><div class="pattern">有点儿 + tính từ / một số động từ tâm lý</div><p>Diễn tả mức độ nhẹ, thường dùng khi nhận xét điều chưa như mong muốn.</p>${grammarExamples([["我觉得汉字有点儿难。","Wǒ juéde Hànzì yǒudiǎnr nán.","Tôi thấy chữ Hán hơi khó."],["今天的作业有点儿多。","Jīntiān de zuòyè yǒudiǎnr duō.","Bài tập hôm nay hơi nhiều."],["我没吃早饭，现在有点儿饿。","Wǒ méi chī zǎofàn, xiànzài yǒudiǎnr è.","Tôi chưa ăn sáng, bây giờ hơi đói."]])}</article><article class="card grammar"><h2>03 · （一）点儿</h2><div class="pattern">Tính từ + （一）点儿</div>${grammarExamples([["快一点儿！","Kuài yìdiǎnr!","Nhanh hơn một chút!"],["慢一点儿！","Màn yìdiǎnr!","Chậm hơn một chút!"],["便宜一点儿吧！","Piányi yìdiǎnr ba!","Rẻ hơn một chút nhé!"]])}<div class="pattern">Động từ + （一）点儿 + danh từ</div>${grammarExamples([["喝一点儿茶。","Hē yìdiǎnr chá.","Uống một chút trà."],["吃一点儿东西。","Chī yìdiǎnr dōngxi.","Ăn một chút đồ ăn."],["买一点儿苹果。","Mǎi yìdiǎnr píngguǒ.","Mua một ít táo."]])}${grammarExamples([["有点儿忙。","Yǒudiǎnr máng.","Hơi bận."],["知道一点儿他的事。","Zhīdào yìdiǎnr tā de shì.","Biết một chút chuyện của anh ấy."]])}</article><a class="btn" href="#practice">Luyện mẫu câu →</a>`+lesson5References(3,4);}
