function gradeLesson5Exercise(mode,index,draft){const q=lesson5Data.exercises[mode][index],variants=[q[1]];if(mode==='choose'&&[3,5].includes(index))variants.push('一点');return {correct:mode==='feelings'?(normalizeHanzi(draft).includes(q[1])||(index===1&&normalizeHanzi(draft).includes('有点儿不好吃'))):variants.some(a=>compareHanzi(draft,a).correct),answer:q[1],note:q[2]};}
