pages.writing=function(){lesson5PreviousPages.writing();if(state.lesson!=='5')return;document.querySelector('#app .eyebrow').textContent='LUYỆN VIẾT · BÀI 5';const chars=[...new Set(lesson5Data.rows.map(r=>r[0]).join('').split('').filter(c=>/[\u3400-\u9fff]/.test(c)))];document.querySelector('#model').innerHTML=chars.map(c=>'<option>'+c+'</option>').join('');document.querySelector('#modelchar').textContent=chars[0];};
