function renderLesson5Pictures(area){area.innerHTML='<article class="card grammar"><h2>Hoạt động cuối tuần theo tranh</h2><p class="sub">Hai ảnh phía trên là ví dụ. Điền ba hoạt động cho ảnh mua sắm, thư viện và sân bóng phía dưới.</p><img loading="lazy" src="images/lesson5/source-5.png" alt="Tranh ví dụ và ba hoạt động cuối tuần trang 55" style="display:block;max-width:100%;width:480px;margin:12px auto">'+[['Mua sắm','买衣服'],['Thư viện','去图书馆'],['Sân bóng','打篮球']].map(([label,answer],i)=>'<label for="lesson5Picture'+i+'">'+(i+1)+'. '+label+'</label><input id="lesson5Picture'+i+'" class="lesson2-answer" lang="zh-CN"><p id="lesson5PictureFeedback'+i+'" role="status"></p>').join('')+'<button class="btn" id="lesson5PictureCheck">Kiểm tra</button><p>问：你周末要做什么？<br>答：我要跟朋友一起……。</p></article>';const answers=['买衣服','去图书馆','打篮球'];for(let i=0;i<3;i++)document.querySelector('#lesson5Picture'+i).value=state.lesson5Exercises?.pictures?.[i]?.draft||'';document.querySelector('#lesson5PictureCheck').onclick=()=>{const records={};answers.forEach((answer,i)=>{const draft=document.querySelector('#lesson5Picture'+i).value,correct=compareHanzi(draft,answer).correct;records[i]={draft,correct};document.querySelector('#lesson5PictureFeedback'+i).textContent=correct?'✓ Chính xác':'Đáp án: '+answer;});state.lesson5Exercises=state.lesson5Exercises||{};state.lesson5Exercises.pictures=records;save();};}
